#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    long long total = (long long)n * (n - 1) / 2;
    long long limit = (long long)n * (n - 1);
    vector<vector<long long>> dp_table(n + 1, vector<long long>(limit + 1, 0));
    vector<vector<long long>> dp1_table(n + 1, vector<long long>(limit + 1, 0));
    dp_table[1][total] = 1;
    for (int i = 2; i <= n; ++i) {
        long long low = total - (long long)(i - 1) * (i - 2) / 2;
        long long high = total + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = low; x <= high; ++x) {
            for (int delta = -i + 1; delta < i; ++delta) {
                long long idx = x + delta;
                if (0 <= idx && idx <= limit) {
                    long long val = (dp_table[i - 1][x] * (i - abs(delta))) % mod;
                    dp_table[i][idx] = (dp_table[i][idx] + val) % mod;
                }
            }
        }
        for (long long x = low; x <= high; ++x) {
            long long val = (dp1_table[i - 1][x] * i) % mod;
            dp1_table[i][x] = (dp1_table[i][x] + val) % mod;
        }
        for (long long x = low; x <= high; ++x) {
            for (int delta = 1; delta < i; ++delta) {
                long long idx = x - delta;
                if (0 <= idx && idx <= limit) {
                    long long val = (dp_table[i - 1][x] * (i - delta)) % mod;
                    dp1_table[i][idx] = (dp1_table[i][idx] + val) % mod;
                }
            }
        }
    }
    long long result = 0;
    for (long long x = total + 1; x <= limit; ++x) {
        result = (result + dp1_table[n][x]) % mod;
    }
    cout << result << "\n";
    return 0;
}
